/* --- Eliminar el esquema MEXICO_CP y sus objetos si ya existen --- */
IF EXISTS (SELECT 1 FROM sys.schemas WHERE name = 'MEXICO_CP')
BEGIN
    IF OBJECT_ID('MEXICO_CP.ASENTAMIENTO', 'U')      IS NOT NULL DROP TABLE [MEXICO_CP].[ASENTAMIENTO];
    IF OBJECT_ID('MEXICO_CP.MUNICIPIO', 'U')         IS NOT NULL DROP TABLE [MEXICO_CP].[MUNICIPIO];
    IF OBJECT_ID('MEXICO_CP.CIUDAD', 'U')            IS NOT NULL DROP TABLE [MEXICO_CP].[CIUDAD];
    IF OBJECT_ID('MEXICO_CP.TIPO_ASENTAMIENTO', 'U') IS NOT NULL DROP TABLE [MEXICO_CP].[TIPO_ASENTAMIENTO];
    IF OBJECT_ID('MEXICO_CP.ESTADO', 'U')            IS NOT NULL DROP TABLE [MEXICO_CP].[ESTADO];
    DROP SCHEMA [MEXICO_CP];
END
GO

CREATE SCHEMA [MEXICO_CP];
GO


BEGIN TRANSACTION;
CREATE TABLE [MEXICO_CP].[ESTADO] 
(id INT PRIMARY KEY,
name NVARCHAR(31));
GO

COMMIT TRANSACTION;
GO

BEGIN TRANSACTION;
GO
COMMIT TRANSACTION;
GO

BEGIN TRANSACTION;
