BEGIN TRANSACTION;
CREATE TABLE [MEXICO_CP].[MUNICIPIO] 
(id INT PRIMARY KEY,
name NVARCHAR(49),
fk_ESTADO INT NULL,
CONSTRAINT FK_MUNICIPIO_fk_ESTADO FOREIGN KEY (fk_ESTADO) REFERENCES [MEXICO_CP].[ESTADO] (id)
);
GO

COMMIT TRANSACTION;
GO

BEGIN TRANSACTION;
GO
