GO
COMMIT TRANSACTION;
GO

BEGIN TRANSACTION;

CREATE TABLE [MEXICO_CP].[ASENTAMIENTO] 
(id INT PRIMARY KEY,
name NVARCHAR(57),
CODIGO_POSTAL NVARCHAR(5),
fk_TIPO_ASENTAMIENTO INT NULL ,
fk_MUNICIPIO INT NULL, 
fk_CIUDAD INT NULL, 
CONSTRAINT FK_ASENTAMIENTO_fk_TIPO_ASENTAMIENTO FOREIGN KEY (fk_TIPO_ASENTAMIENTO) REFERENCES [MEXICO_CP].[TIPO_ASENTAMIENTO] (id),
CONSTRAINT FK_ASENTAMIENTO_fk_MUNICIPIO FOREIGN KEY (fk_MUNICIPIO) REFERENCES [MEXICO_CP].[MUNICIPIO] (id),
CONSTRAINT FK_ASENTAMIENTO_fk_CIUDAD FOREIGN KEY (fk_CIUDAD) REFERENCES [MEXICO_CP].[CIUDAD] (id)
);
GO

CREATE INDEX cp_idx ON MEXICO_CP.ASENTAMIENTO (CODIGO_POSTAL);

