/* --- Indice por codigo postal --- */
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'cp_idx' AND object_id = OBJECT_ID('MEXICO_CP.ASENTAMIENTO'))
    CREATE INDEX cp_idx ON [MEXICO_CP].[ASENTAMIENTO] (CODIGO_POSTAL);
